"""
Validation script for pipeline outputs.
Checks existence, non-emptiness, and structure of expected output files.
"""

import csv
import json
import os
from pathlib import Path


def check_file_exists(path: str) -> dict:
    """Check if a file exists."""
    exists = os.path.isfile(path)
    return {
        "check_name": f"file_exists:{path}",
        "passed": exists,
        "message": f"File {path} exists" if exists else f"File {path} does not exist"
    }


def check_file_not_empty(path: str) -> dict:
    """Check if a file is not empty."""
    if not os.path.isfile(path):
        return {
            "check_name": f"file_not_empty:{path}",
            "passed": False,
            "message": f"File {path} does not exist, cannot check emptiness"
        }

    size = os.path.getsize(path)
    return {
        "check_name": f"file_not_empty:{path}",
        "passed": size > 0,
        "message": f"File {path} has {size} bytes" if size > 0 else f"File {path} is empty"
    }


def check_csv_has_header(path: str, expected_columns: list) -> dict:
    """Check if a CSV file has the expected header columns."""
    if not os.path.isfile(path):
        return {
            "check_name": f"csv_header:{path}",
            "passed": False,
            "message": f"File {path} does not exist"
        }

    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return {
                    "check_name": f"csv_header:{path}",
                    "passed": False,
                    "message": f"File {path} has no header row"
                }

            missing = [col for col in expected_columns if col not in header]
            if missing:
                return {
                    "check_name": f"csv_header:{path}",
                    "passed": False,
                    "message": f"File {path} missing columns: {missing}"
                }

            return {
                "check_name": f"csv_header:{path}",
                "passed": True,
                "message": f"File {path} has all expected columns"
            }
    except Exception as e:
        return {
            "check_name": f"csv_header:{path}",
            "passed": False,
            "message": f"Error reading {path}: {str(e)}"
        }


def check_csv_has_data(path: str) -> dict:
    """Check if a CSV file has data rows (beyond header)."""
    if not os.path.isfile(path):
        return {
            "check_name": f"csv_has_data:{path}",
            "passed": False,
            "message": f"File {path} does not exist"
        }

    try:
        with open(path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                return {
                    "check_name": f"csv_has_data:{path}",
                    "passed": False,
                    "message": f"File {path} has no header row"
                }

            row_count = sum(1 for row in reader)
            return {
                "check_name": f"csv_has_data:{path}",
                "passed": row_count > 0,
                "message": f"File {path} has {row_count} data rows"
            }
    except Exception as e:
        return {
            "check_name": f"csv_has_data:{path}",
            "passed": False,
            "message": f"Error reading {path}: {str(e)}"
        }


def main():
    """Run all validation checks and write summary JSON."""
    results = []

    # Define expected files and their expected columns
    files_to_check = [
        {
            "path": "outputs/t01_selected_indicators.csv",
            "columns": ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]
        },
        {
            "path": "outputs/t05_clean_stops.csv",
            "columns": ["stop_id", "stop_name", "stop_lat", "stop_lon"]
        },
        {
            "path": "outputs/t08_pois_clean.csv",
            "columns": ["qid", "label", "poi_type", "latitude", "longitude", "source"]
        },
        {
            "path": "outputs/t10_accessibility_scores.csv",
            "columns": ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]
        },
        {
            "path": "outputs/t13_city_clusters.csv",
            "columns": ["city_id", "city_name", "year", "cluster_id"]
        }
    ]

    # Run checks for each file
    for file_info in files_to_check:
        path = file_info["path"]
        columns = file_info["columns"]

        # Check 1: File exists
        results.append(check_file_exists(path))

        # Check 2: File not empty
        results.append(check_file_not_empty(path))

        # Check 3: CSV has expected header
        results.append(check_csv_has_header(path, columns))

        # Check 4: CSV has data rows
        results.append(check_csv_has_data(path))

    # Additional check: verify all files are present (summary check)
    all_exist = all(os.path.isfile(f["path"]) for f in files_to_check)
    results.append({
        "check_name": "all_files_present",
        "passed": all_exist,
        "message": "All expected output files are present" if all_exist else "Some expected output files are missing"
    })

    # Ensure output directory exists
    output_dir = Path("outputs")
    output_dir.mkdir(parents=True, exist_ok=True)

    # Write results to JSON
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    print(f"Validation complete. Results written to {output_path}")

    # Print summary
    passed = sum(1 for r in results if r["passed"])
    total = len(results)
    print(f"Passed: {passed}/{total} checks")


if __name__ == "__main__":
    main()
